        function w(m) { printf "W\t%s:%d: %s\n", f, NR, m }
        # names compare as the drift check matches them: case and "-", "_", " " folded
        function norm(x) { x = tolower(x); gsub(/[-_ ]+/, " ", x); gsub(/^ | $/, "", x); return x }
