            hd = $0; sub(/^## +/, "", hd); sub(/[[:space:]]+$/, "", hd)
            if (hd == "Language") { if (lang_line) v("a second \"## Language\" section (the first is on line " lang_line ")"); else lang_line = NR; lang = 1 }
            else lang = 0
